import sympy
from sympy.combinatorics import PermutationGroup, Permutation
from sympy.combinatorics.named_groups import SymmetricGroup, AlternatingGroup, DihedralGroup, CyclicGroup

# To represent fields and their extensions, we use the Galois correspondence.
# A finite Galois extension E/F is represented by its Galois group G.
# Intermediate fields K and L correspond to subgroups H_K and H_L of G.
# K/F is Galois iff H_K is a normal subgroup of G.
# The intersection K \cap L corresponds to the subgroup generated by H_K and H_L.
# The witness should be a tuple: (G, H_K, H_L)

S3 = SymmetricGroup(3)
S4 = SymmetricGroup(4)
A4 = AlternatingGroup(4)
D4 = DihedralGroup(4)
C4 = CyclicGroup(4)
Z2 = CyclicGroup(2)
Z3 = CyclicGroup(3)
Z4 = CyclicGroup(4)
Z6 = CyclicGroup(6)
trivial = CyclicGroup(1)

# V4 is the Klein four-group, normal in S4
V4 = PermutationGroup([
    Permutation([[0, 1], [2, 3]]),
    Permutation([[0, 2], [1, 3]])
])

def is_subgroup(H, G):
    try:
        return all(G.contains(h) for h in H.generators)
    except Exception:
        return False

def is_normal(H, G):
    try:
        if not is_subgroup(H, G):
            return False
        for g in G.generators:
            for h in H.generators:
                conj = g * h * (~g)
                if not H.contains(conj):
                    return False
        return True
    except Exception:
        return False

def conditions(witness):
    try:
        G, H_K, H_L = witness
    except Exception:
        return [False] * 5

    # H_1: F is a field
    try:
        h1 = isinstance(G, PermutationGroup)
    except Exception:
        h1 = False

    # H_2: K and L are finite field extensions of F
    try:
        h2 = (isinstance(H_K, PermutationGroup) and 
              isinstance(H_L, PermutationGroup) and 
              is_subgroup(H_K, G) and 
              is_subgroup(H_L, G))
    except Exception:
        h2 = False

    # H_3: K and L are contained in a common extension field
    try:
        # In our Galois correspondence model, being subgroups of the same G
        # means they are subfields of the same Galois extension E.
        h3 = h2
    except Exception:
        h3 = False

    # H_4: K/F is a Galois extension
    try:
        h4 = is_normal(H_K, G)
    except Exception:
        h4 = False

    # ¬Q: K \cap L is not a Galois extension of F
    try:
        gens = list(H_K.generators) + list(H_L.generators)
        if not gens:
            # Both are trivial, so their generated subgroup is trivial and thus normal
            neg_q = False
        else:
            H_int = PermutationGroup(gens)
            neg_q = not is_normal(H_int, G)
    except Exception:
        neg_q = False

    return [h1, h2, h3, h4, neg_q]

CONDITION_LABELS = [
    "H_1: F is a field",
    "H_2: K and L are finite field extensions of F",
    "H_3: K and L are contained in a common extension field",
    "H_4: K/F is a Galois extension",
    "¬Q: K \\cap L is not a Galois extension of F"
]

